def index(key, um):
    maker, name, form, A, terms, rng, nd, vd = GLASSES[key]
    if form == "sellmeier":
        s = 1 + A + sum(B * um * um / (um * um - C) for B, C in terms)
    else:
        s = A + sum(c * um ** p for c, p in terms)
    return math.sqrt(s)


def abbe(key):
    nd = index(key, LINE_D)
    return nd, (nd - 1) / (index(key, LINE_F) - index(key, LINE_C))


def psi(um):
    p1 = (um ** -2 - LINE_D ** -2) / (LINE_F ** -2 - LINE_C ** -2)
    p2 = (um ** -4 - LINE_D ** -4) - (LINE_F ** -4 - LINE_C ** -4) * p1
    p3 = (um ** 2 - LINE_D ** 2) - (LINE_F ** 2 - LINE_C ** 2) * p1
    return p1, p2, p3


def model_index(coef, nd, vd, um):
    a1, b1, a2, b2 = coef
    p1, p2, p3 = psi(um)
    return nd + (nd - 1) / vd * (p1 + (a1 + b1 * vd) * p2 + (a2 + b2 * vd) * p3)


def log_samples(lo, hi, count):
    return [lo * (hi / lo) ** (i / (count - 1)) for i in range(count)]


def solve(a, b):
    n = len(b)
    m = [row[:] + [b[i]] for i, row in enumerate(a)]
    for i in range(n):
        p = max(range(i, n), key=lambda r: abs(m[r][i]))
        m[i], m[p] = m[p], m[i]
        for r in range(n):
            if r != i:
                f = m[r][i] / m[i][i]
                for c in range(i, n + 1):
                    m[r][c] -= f * m[i][c]
    return [m[i][n] / m[i][i] for i in range(n)]


MODEL_RANGE = (365.0, 1014.0)


def fit_model():
    """Least squares on y = sum (a_k + b_k Vd) psi_k for k = 2, 3, where
    y = (n - nd)/(nF - nC) - psi1, with each glass's fitted nd and Vd."""
    rows, ys = [], []
    for key in GLASSES:
        rng = GLASSES[key][5]
        nd, vd = abbe(key)
        lo, hi = max(MODEL_RANGE[0], rng[0]), min(MODEL_RANGE[1], rng[1])
        for nm in log_samples(lo, hi, 31):
            um = nm / 1000
            p1, p2, p3 = psi(um)
            rows.append([p2, vd * p2, p3, vd * p3])
            ys.append((index(key, um) - nd) / ((nd - 1) / vd) - p1)
    ata = [[sum(r[i] * r[j] for r in rows) for j in range(4)] for i in range(4)]
    aty = [sum(r[i] * y for r, y in zip(rows, ys)) for i in range(4)]
    a1, b1, a2, b2 = solve(ata, aty)
    return (a1, b1, a2, b2)


ERROR_RANGES = {"visible": (435.8, 706.5), "main": (404.7, 1014.0), "ultraviolet": (365.0, 404.7)}


def ceil_sig(value, digits=2):
    scale = 10 ** (digits - 1 - math.floor(math.log10(abs(value))))
    return math.ceil(value * scale - 1e-9) / scale


def model_errors(coef):
    out = {}
    for label, (lo0, hi0) in ERROR_RANGES.items():
        errs = []
        for key in GLASSES:
            rng = GLASSES[key][5]
            lo, hi = max(lo0, rng[0]), min(hi0, rng[1])
            if lo >= hi:
                continue
            nd, vd = abbe(key)
            for nm in log_samples(lo, hi, 41):
                errs.append(abs(model_index(coef, nd, vd, nm / 1000) - index(key, nm / 1000)))
        errs.sort()
        out[label] = {"median": errs[len(errs) // 2], "p95": errs[int(0.95 * len(errs))], "max": errs[-1]}
    return out


def cases():
    out = []
    for key, (maker, name, form, A, terms, rng, nd, vd) in GLASSES.items():
        fit_nd, fit_vd = abbe(key)
        assert abs(fit_nd - nd) < 1e-5 and abs(fit_vd - vd) < 0.01, (name, fit_nd, nd, fit_vd, vd)
        out.append({
            "name": f"{name} ({maker.upper()}) nd and Vd versus the catalogue",
            "inputs": {"kind": "abbe", "record": key},
            "expected": {"nd": nd, "vd": vd},
            "tolerance": {"nd": 1e-5, "vd": 0.01},
            "absolute": True,
            "note": "the catalogue's printed nd and Vd",
        })
        for nm, n in DATASHEET_LINES.get(key, []):
            assert abs(index(key, nm / 1000) - n) <= 5.1e-6, (name, nm, n)
            out.append({
                "name": f"{name} at {nm} nm versus the data sheet",
                "inputs": {"kind": "index", "record": key, "wavelengthNm": nm},
                "expected": {"index": n},
                "tolerance": {"index": 1e-5},
                "absolute": True,
                "note": "tabulated on the manufacturer's data sheet",
            })
        lo, hi = rng
        for nm in (lo, (lo + hi) / 2, hi):
            out.append({
                "name": f"{name} evaluated at {sig(nm, 6)} nm",
                "inputs": {"kind": "index", "record": key, "wavelengthNm": nm},
                "expected": {"index": sig(index(key, nm / 1000), 15)},
                "tolerance": {"index": 1e-9},
                "absolute": True,
                "note": "transcription check of the dataset's formula",
            })
    coef = fit_model()
    out.append({
        "name": "model glass coefficients refitted to the 84 catalogue glasses",
        "inputs": {"kind": "model-coefficients"},
        "expected": dict(zip(("a1", "b1", "a2", "b2"), (sig(c, 12) for c in coef))),
        "tolerance": {"a1": 1e-6, "b1": 1e-6, "a2": 1e-6, "b2": 1e-6},
        "absolute": True,
        "note": "least squares over 365-1014 nm",
    })
    for label, stats in model_errors(coef).items():
        out.append({
            "name": f"model glass error against the catalogue, {label} range {ERROR_RANGES[label][0]}-{ERROR_RANGES[label][1]} nm",
            "inputs": {"kind": "model-error", "range": label},
            "expected": {k: (ceil_sig(v) if k == "max" else sig(v, 2)) for k, v in stats.items()},
            "tolerance": {k: 0.05 for k in stats},
            "note": "the stated error, to the two significant figures it is stated with; the maximum rounded up, so that it bounds every sample",
        })
    for key in ("nbk7", "nsf11", "slah64", "efd10"):
        nd, vd = GLASSES[key][6], GLASSES[key][7]
        for nm in (365.0, 486.1327, 587.5618, 656.2725, 1014.0):
            out.append({
                "name": f"model glass nd {nd}, Vd {vd} at {nm} nm",
                "inputs": {"kind": "model", "nd": nd, "vd": vd, "wavelengthNm": nm},
                "expected": {"index": sig(model_index(coef, nd, vd, nm / 1000), 12)},
                "tolerance": {"index": 2e-6},
                "absolute": True,
                "note": "the model's formula with this module's fit; 2e-6 allows the 1e-6 coefficient tolerance",
            })
    return out


